j2:if.script:
        function openFindingCondition(){
			var d = new GlideModalForm('Create new condition', 'promin_finding_def_condition');
			d.setOnloadCallback(populateModal);
			d.setCompletionCallback(function(action_verb, sys_id, table, displayValue) {
				g_form.setValue("source_condition", sys_id);
			});
			d.render();

			function populateModal() {
				//Access GlideModal g_form
				var source_condition_form = window.frames["dialog_frame"].g_form;

				var findingConfigType = g_scratchpad.findingConfigType;
				var findingProcessTable = g_scratchpad.findingProcessTable;
				var findingDefSysId = g_scratchpad.findingDefSysId;
				var newTableName = '';
				source_condition_form.removeOption("type", "CONTEXT");

				if(findingConfigType == "PROCESS"){
					newTableName = findingProcessTable;
					source_condition_form.setDisplay('entity', false);
				} 
				if(findingConfigType == "PROJECT"){
					source_condition_form.setMandatory('entity', true);
				} 
				if(newTableName != '') {
					source_condition_form.setValue("table", newTableName);
					source_condition_form.setReadOnly("table", true);
				}
				if(findingDefSysId != '') {
					source_condition_form.setValue("finding_def", findingDefSysId);
					source_condition_form.setReadOnly("finding_def", true);
				}
			}
        }
